css:
.custombuild-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2433;
    background: linear-gradient(160deg, #f4f1ea 0%, #eae4d6 100%);
    border-radius: 18px;
}

.custombuild-container * {
    box-sizing: border-box;
}

.custombuild-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #16213e 0%, #1f2d52 55%, #2a3a6b 100%);
    color: #f6f3ec;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(22, 33, 62, 0.32);
    border-bottom: 4px solid #c79a3e;
}

.custombuild-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    font-family: Georgia, 'Times New Roman', serif;
}

.custombuild-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ecd7a3;
    background: rgba(199, 154, 62, 0.18);
    padding: 5px 14px;
    border-radius: 999px;
}

.custombuild-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e6e0d2;
}

.custombuild-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2a3a6b;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.custombuild-period-counter #currentDay,
.custombuild-period-counter #maxPeriods {
    font-weight: 800;
    color: #16213e;
}

.custombuild-round-name {
    background: #e2dbc8;
    color: #16213e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.custombuild-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a3b1c;
    background: #f6e2d6;
    padding: 4px 12px;
    border-radius: 999px;
}

.custombuild-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.custombuild-status-card {
    background: #fffdf8;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0d8c4;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.07);
    border-top: 4px solid #2a3a6b;
}

.custombuild-card-fit { border-top-color: #1f6f5c; }
.custombuild-card-impact { border-top-color: #2a4f93; }
.custombuild-card-margin { border-top-color: #c79a3e; }
.custombuild-card-nps { border-top-color: #6a4a8f; }

.custombuild-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b6452;
}

.custombuild-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #16213e;
}

.custombuild-card-fit .custombuild-value { color: #1f6f5c; }
.custombuild-card-impact .custombuild-value { color: #2a4f93; }
.custombuild-card-margin .custombuild-value { color: #b07f1e; }
.custombuild-card-nps .custombuild-value { color: #6a4a8f; }

.custombuild-sublabel {
    font-size: 0.76rem;
    color: #857c66;
    line-height: 1.35;
}

.custombuild-margin-fail .custombuild-value { color: #c0392b; }
.custombuild-margin-ok .custombuild-value { color: #1f6f5c; }

.custombuild-nps-win .custombuild-value { color: #1f6f5c; }

.custombuild-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #16213e;
    color: #f1ede2;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 5px solid #c79a3e;
}

.custombuild-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #ecd7a3;
}

.custombuild-budget-over #budgetDisplay {
    color: #ff9b87;
}

.custombuild-briefing {
    display: flex;
    gap: 14px;
    background: #fffdf8;
    border-left: 5px solid #2a3a6b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.05);
}

.custombuild-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.custombuild-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #16213e;
    margin-bottom: 6px;
    font-family: Georgia, 'Times New Roman', serif;
}

.custombuild-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #36405a;
}

.custombuild-briefing-text strong { color: #1f6f5c; }
.custombuild-briefing-text em { color: #9a3b1c; font-style: italic; }

.custombuild-controls {
    background: #fffdf8;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0d8c4;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.07);
}

.custombuild-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #16213e;
    border-bottom: 2px solid #eae4d6;
    padding-bottom: 8px;
}

.custombuild-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #28324c;
    margin: 14px 0 6px;
}

.custombuild-container select,
.custombuild-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cabf9f;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbf8f0;
    color: #1d2433;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.custombuild-container select:focus,
.custombuild-container input[type="number"]:focus {
    outline: none;
    border-color: #c79a3e;
    box-shadow: 0 0 0 3px rgba(199, 154, 62, 0.18);
}

.custombuild-container select option {
    background-color: #ffffff;
    color: #1d2433;
}

.custombuild-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c79a3e;
}

.custombuild-range-readout,
.custombuild-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2a3a6b;
    margin-top: 4px;
}

.custombuild-range-readout span:nth-child(2),
.custombuild-alloc-readout span:nth-child(2) {
    color: #1f6f5c;
    font-weight: 800;
}

.custombuild-hint {
    font-size: 0.8rem;
    color: #857c66;
    margin-top: 4px;
    line-height: 1.4;
}

.custombuild-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.custombuild-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f5f1e6;
    border: 1px solid #e3dbc6;
    border-radius: 9px;
    padding: 8px 12px;
}

.custombuild-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #28324c;
}

.custombuild-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.custombuild-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.custombuild-container .btn-primary {
    background: linear-gradient(135deg, #16213e 0%, #2a3a6b 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(22, 33, 62, 0.28);
    color: #f6f3ec;
}

.custombuild-container .btn-primary:hover {
    filter: brightness(1.12);
}

.custombuild-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cabf9f;
    color: #6b6452;
}

.custombuild-coach {
    background: #16213e;
    color: #eef0f6;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(22, 33, 62, 0.24);
    border-left: 5px solid #c79a3e;
}

.custombuild-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #ecd7a3;
    margin-bottom: 8px;
}

.custombuild-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.custombuild-coach-body strong { color: #f3d488; }
.custombuild-coach-body em { color: #ffc1ad; font-style: italic; }

.custombuild-history,
.custombuild-chart {
    background: #fffdf8;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0d8c4;
    box-shadow: 0 4px 14px rgba(22, 33, 62, 0.07);
}

.custombuild-history h3,
.custombuild-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #16213e;
    font-family: Georgia, 'Times New Roman', serif;
}

.custombuild-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #28324c;
}

.custombuild-container table#usfHistoryTable th {
    background: #efeadb;
    color: #16213e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #ddd3ba;
}

.custombuild-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #efeadb;
}

.custombuild-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7ee;
}

.custombuild-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .custombuild-container {
        padding: 14px;
    }
    .custombuild-header h1 {
        font-size: 1.7rem;
    }
    .custombuild-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .custombuild-value {
        font-size: 2rem;
    }
    .custombuild-clock {
        margin-left: 0;
    }
    .custombuild-period-counter {
        font-size: 0.88rem;
    }
    .custombuild-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .custombuild-alloc-row {
        flex-wrap: wrap;
    }
    .custombuild-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .custombuild-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (light theme, custombuild) ---- */
.custombuild-completion { padding: 8px 4px 4px; }
.custombuild-cm-head { text-align: center; margin-bottom: 16px; }
.custombuild-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #1f7a52; }
.custombuild-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #5b9b7d; }
.custombuild-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #11203b; }
.custombuild-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.custombuild-cm-yes { background: rgba(31,122,82,0.14); color: #1a7059; border: 1px solid rgba(31,122,82,0.5); }
.custombuild-cm-no { background: rgba(192,86,31,0.12); color: #b0521f; border: 1px solid rgba(192,86,31,0.45); }
.custombuild-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.custombuild-cm-metric { flex: 1 1 110px; min-width: 100px; background: rgba(42,74,122,0.08); border: 1px solid rgba(42,74,122,0.22); border-radius: 10px; padding: 10px 8px; text-align: center; }
.custombuild-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #2a4a7a; }
.custombuild-cm-ml { display: block; font-size: 0.72rem; margin-top: 4px; color: #5a6577; text-transform: uppercase; letter-spacing: 0.03em; }
.custombuild-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #11203b; }
.custombuild-cm-insights { margin: 0; padding-left: 20px; }
.custombuild-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #2b3547; }

