(function() {
    'use strict';

    class CustomBuildAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Custom Build`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Aurora Health / Lakeshore).
            this.BUDGET_CAP = 1200;        // USD 1,200k total, fixed
            this.FACULTY_DAYS = 18;        // ~18 faculty-days fund
            this.MARQUEE_FEE = 22;         // USD 22k / marquee tenured day
            this.PRACTICE_FEE = 9;         // USD 9k / professor-of-practice day
            this.COACH_HOUR = 0.45;        // USD 450 / coaching hour, in $k
            this.LEADERS = 180;            // leaders to develop
            this.MARGIN_FLOOR = 30;        // % gross-margin sustainability floor
            this.START_NPS = 50;           // projected NPS at scoping (unit benchmark 71)
            this.BENCHMARK_NPS = 71;       // last year's client-survey NPS
            this.TARGET_FIT = 75;          // win the right work threshold
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    fit: 20,
                    impact: 15,
                    nps: this.START_NPS,
                    margin: 100,           // before any cost is committed
                    budgetUsed: 0,
                    overBudget: false,
                    marginBreached: false,
                    fitHistory: [20],
                    impactHistory: [15],
                    npsHistory: [this.START_NPS],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    diag: `leadchange`,
                    target: `segmented`,
                    diagDepth: 60,
                    ratio: 60,
                    journey: `backward`,
                    waves: `fourwaves`,
                    modules: 8,
                    marquee: 6,
                    practice: 12,
                    sim: `yes`,
                    coaching: 3,
                    ops: 120,
                    metrics: `l3l4`,
                    npsTarget: `credible`,
                    pitch: `diagnosis`,
                    conviction: 70
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const dg = document.getElementById(`diagInput`);
                const tg = document.getElementById(`targetInput`);
                const dd = document.getElementById(`diagDepthInput`);
                if (dg) decisions.diag = dg.value;
                if (tg) decisions.target = tg.value;
                if (dd) decisions.diagDepth = parseInt(dd.value, 10);
                if (!Number.isFinite(decisions.diagDepth) || decisions.diagDepth < 0 || decisions.diagDepth > 100) {
                    warn(`warn_diagdepth_range`); return false;
                }
            } else if (round === 2) {
                const ra = document.getElementById(`ratioInput`);
                const jo = document.getElementById(`journeyInput`);
                const wa = document.getElementById(`wavesInput`);
                const mo = document.getElementById(`modulesInput`);
                if (ra) decisions.ratio = parseInt(ra.value, 10);
                if (jo) decisions.journey = jo.value;
                if (wa) decisions.waves = wa.value;
                if (mo) decisions.modules = parseInt(mo.value, 10);
                if (!Number.isFinite(decisions.ratio) || decisions.ratio < 0 || decisions.ratio > 100) {
                    warn(`warn_ratio_range`); return false;
                }
                if (!Number.isFinite(decisions.modules) || decisions.modules < 3 || decisions.modules > 40) {
                    warn(`warn_modules_range`); return false;
                }
            } else if (round === 3) {
                const mq = document.getElementById(`marqueeInput`);
                const pr = document.getElementById(`practiceInput`);
                const si = document.getElementById(`simInput`);
                const co = document.getElementById(`coachingInput`);
                const op = document.getElementById(`opsInput`);
                if (mq) decisions.marquee = parseFloat(mq.value);
                if (pr) decisions.practice = parseFloat(pr.value);
                if (si) decisions.sim = si.value;
                if (co) decisions.coaching = parseFloat(co.value);
                if (op) decisions.ops = parseFloat(op.value);
                const facParts = [decisions.marquee, decisions.practice];
                if (facParts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_faculty_negative`); return false;
                }
                const totalDays = Math.round((decisions.marquee + decisions.practice) * 100) / 100;
                if (Math.abs(totalDays - this.FACULTY_DAYS) > 0.001) {
                    warn(`warn_faculty_total`); return false;
                }
                if (!Number.isFinite(decisions.coaching) || decisions.coaching < 0) {
                    warn(`warn_coaching_negative`); return false;
                }
                if (!Number.isFinite(decisions.ops) || decisions.ops < 0) {
                    warn(`warn_ops_negative`); return false;
                }
            } else if (round === 4) {
                const me = document.getElementById(`metricsInput`);
                const nt = document.getElementById(`npsTargetInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (me) decisions.metrics = me.value;
                if (nt) decisions.npsTarget = nt.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let fitDelta = 0, impactDelta = 0, npsDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Scope the REAL challenge — diagnosis before design (Common Error 1).
                switch (d.diag) {
                    case `leadchange`: fitDelta += 15; impactDelta += 4; npsDelta += 3; coachKey = `coach_r1_diag_right`; break;
                    case `fourtracks`: fitDelta -= 8; impactDelta -= 3; npsDelta -= 2; coachKey = `coach_r1_fourtracks`; break;
                    case `technical`: fitDelta -= 6; impactDelta -= 2; npsDelta -= 2; coachKey = `coach_r1_technical`; break;
                    case `morale`: fitDelta -= 9; impactDelta -= 3; npsDelta -= 2; coachKey = `coach_r1_morale`; break;
                }

                // Segment the 180 vs treat as one cohort (cohort-logistics error).
                switch (d.target) {
                    case `segmented`: fitDelta += 8; impactDelta += 3; if (d.diag === `leadchange`) coachKey = `coach_r1_sharp`; break;
                    case `uniform`: fitDelta -= 6; npsDelta -= 2; coachKey = `coach_r1_uniform`; break;
                    case `toponly`: fitDelta -= 8; impactDelta -= 2; coachKey = `coach_r1_toponly`; break;
                }

                // Diagnosis discipline before designing.
                if (d.diagDepth >= 60) { fitDelta += 5; }
                else if (d.diagDepth <= 25) { fitDelta -= 5; coachKey = `coach_r1_shallow`; }

                summaryKey = (d.diag === `leadchange` && d.target === `segmented`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Learning architecture: 70-20-10 experience-to-content (Common Error 3 seed).
                if (d.ratio >= 60 && d.ratio <= 80) { impactDelta += 12; fitDelta += 4; coachKey = `coach_r2_ratio_right`; }
                else if (d.ratio >= 40 && d.ratio < 60) { impactDelta += 5; coachKey = `coach_r2_ratio_mid`; }
                else if (d.ratio < 40) { impactDelta -= 6; npsDelta -= 2; coachKey = `coach_r2_ratio_low`; }
                else { impactDelta -= 2; coachKey = `coach_r2_ratio_high`; }

                // Design backward from outcomes vs from a content menu.
                switch (d.journey) {
                    case `backward`: fitDelta += 8; impactDelta += 5; if (d.ratio >= 60 && d.ratio <= 80) coachKey = `coach_r2_backward`; break;
                    case `menu`: fitDelta -= 6; impactDelta -= 4; npsDelta -= 2; coachKey = `coach_r2_menu`; break;
                    case `frontload`: impactDelta -= 5; coachKey = `coach_r2_frontload`; break;
                }

                // Cohort / wave plan — 180 cannot empty the wards at once.
                switch (d.waves) {
                    case `fourwaves`: fitDelta += 6; impactDelta += 3; break;
                    case `onewave`: fitDelta -= 8; npsDelta -= 2; coachKey = `coach_r2_onewave`; break;
                    case `twowaves`: fitDelta += 2; break;
                }

                // Module count — over-stuffing (Common Error 2).
                if (d.modules >= 5 && d.modules <= 12) { fitDelta += 5; }
                else if (d.modules >= 13 && d.modules <= 20) { fitDelta -= 4; coachKey = `coach_r2_manymods`; }
                else if (d.modules > 20) { fitDelta -= 8; impactDelta -= 3; coachKey = `coach_r2_overstuff`; }
                else { fitDelta -= 4; coachKey = `coach_r2_thin`; }

                summaryKey = (d.ratio >= 60 && d.ratio <= 80 && d.journey === `backward` && d.modules <= 12) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Allocate faculty-days & modules under budget (Common Errors 3 & 5).
                const facCost = d.marquee * this.MARQUEE_FEE + d.practice * this.PRACTICE_FEE;
                const coachCost = d.coaching * this.LEADERS * this.COACH_HOUR;
                let simCost = 0;
                spend = 0;

                // Faculty mix: 70-20-10 favours practice/applied over marquee lecture.
                if (d.marquee <= 9 && d.practice >= d.marquee) { impactDelta += 7; coachKey = `coach_r3_practice`; }
                else if (d.marquee >= 12) { impactDelta -= 9; fitDelta -= 4; npsDelta -= 3; coachKey = `coach_r3_marquee`; }
                else { impactDelta += 1; }

                // Bespoke simulation — the experiential core that shifts behaviour.
                switch (d.sim) {
                    case `yes`: simCost = 60; impactDelta += 10; fitDelta += 3; coachKey = (d.marquee <= 9) ? `coach_r3_sim` : coachKey; break;
                    case `off`: simCost = 20; impactDelta += 4; break;
                    case `no`: simCost = 0; impactDelta -= 7; coachKey = `coach_r3_nosim`; break;
                }

                // Coaching pool — the "20" of 70-20-10.
                if (d.coaching >= 2) { impactDelta += 9; }
                else if (d.coaching >= 1) { impactDelta += 4; }
                else { impactDelta -= 7; coachKey = `coach_r3_nocoaching`; }

                // Operations to run four waves.
                if (d.ops >= 80) { fitDelta += 5; impactDelta += 2; }
                else if (d.ops >= 40) { fitDelta += 1; }
                else { fitDelta -= 8; npsDelta -= 3; coachKey = `coach_r3_thinops`; }

                spend = facCost + simCost + coachCost + d.ops;

                summaryKey = (d.marquee <= 9 && d.sim === `yes` && d.coaching >= 2 && d.ops >= 80) ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Success metrics & pitch — Kirkpatrick L3/L4 (Common Error 4).
                switch (d.metrics) {
                    case `l3l4`: impactDelta += 10; npsDelta += 7; fitDelta += 3; coachKey = `coach_r4_l3l4`; break;
                    case `mixed`: impactDelta += 2; npsDelta += 2; coachKey = `coach_r4_mixed`; break;
                    case `smile`: impactDelta -= 9; npsDelta -= 6; coachKey = `coach_r4_smile`; break;
                }

                // NPS target — over-promising the client cannot verify.
                switch (d.npsTarget) {
                    case `credible`: npsDelta += 8; break;
                    case `stretch`: npsDelta -= 4; coachKey = `coach_r4_stretch`; break;
                    case `vague`: npsDelta -= 2; coachKey = `coach_r4_vague`; break;
                }

                // The pitch frame.
                switch (d.pitch) {
                    case `diagnosis`: fitDelta += 6; npsDelta += 6; impactDelta += 3; coachKey = (d.metrics === `l3l4`) ? `coach_r4_diagnosis` : coachKey; break;
                    case `overpromise`: fitDelta -= 6; npsDelta -= 7; coachKey = `coach_r4_overpromise`; break;
                    case `prestige`: fitDelta -= 4; npsDelta -= 4; coachKey = `coach_r4_prestige`; break;
                }

                // Conviction nudge.
                fitDelta += Math.round((d.conviction - 60) / 12);

                summaryKey = (d.metrics === `l3l4` && d.npsTarget === `credible` && d.pitch === `diagnosis`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- resource accounting (budget / margin) ----
            ds.budgetUsed = Math.round(ds.budgetUsed + spend);
            ds.overBudget = ds.budgetUsed > this.BUDGET_CAP;
            const cost = Math.min(ds.budgetUsed, this.BUDGET_CAP * 1.5);
            ds.margin = Math.round(((this.BUDGET_CAP - cost) / this.BUDGET_CAP) * 100);

            // Margin discipline: pricing at cost / over-spending punishes NPS & fit
            // (Common Error 5 — winning at the expense of sustainable delivery).
            if (ds.budgetUsed > this.BUDGET_CAP) {
                npsDelta -= 14; fitDelta -= 8; ds.marginBreached = true;
                if (round >= 3) coachKey = `coach_r3_overbudget`;
            } else if (ds.margin < this.MARGIN_FLOOR) {
                npsDelta -= 8; fitDelta -= 4; ds.marginBreached = true;
                if (round >= 3 && coachKey === `coach_default`) coachKey = `coach_r3_thinmargin`;
            }

            // NPS also tracks the genuine health of fit + impact this round.
            npsDelta += Math.round((fitDelta + impactDelta) / 12);

            // Apply.
            ds.fit = Math.max(0, Math.min(100, ds.fit + fitDelta));
            ds.impact = Math.max(0, Math.min(100, ds.impact + impactDelta));
            ds.nps = Math.max(0, Math.min(100, ds.nps + npsDelta));

            ds.fitHistory.push(Math.round(ds.fit));
            ds.impactHistory.push(Math.round(ds.impact));
            ds.npsHistory.push(Math.round(ds.nps));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                fit: Math.round(ds.fit),
                fitDelta: Math.round(fitDelta),
                impact: Math.round(ds.impact),
                impactDelta: Math.round(impactDelta),
                nps: Math.round(ds.nps),
                npsDelta: Math.round(npsDelta),
                margin: ds.margin,
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                marginBreached: ds.marginBreached,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

