        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const fit = Math.round(ds.fit);
            const impact = Math.round(ds.impact);
            const nps = Math.round(ds.nps);
            const margin = ds.margin;
            const composite = Math.round(
                Math.min(100, fit) * 0.35 +
                impact * 0.30 +
                Math.min(100, nps) * 0.20 +
                Math.max(0, Math.min(100, margin)) * 0.15
            );
            return Math.max(0, Math.min(100, composite));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.totalScore === `number`) ? s.totalScore
                : (typeof s.overallScore === `number` ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!(s.wonBid && s.sustainable && s.realImpact);
            const badge = met
                ? `<span class="custombuild-cm-badge custombuild-cm-yes">` + T(`cm_won`) + `</span>`
                : `<span class="custombuild-cm-badge custombuild-cm-no">` + T(`cm_notwon`) + `</span>`;
            const failBadge = s.overBudget
                ? ` <span class="custombuild-cm-badge custombuild-cm-no">` + T(`cm_overbudget`) + `</span>`
                : (!s.wonBid ? ` <span class="custombuild-cm-badge custombuild-cm-no">` + T(`cm_lost`) + `</span>` : ``);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="custombuild-cm-metric"><span class="custombuild-cm-mv">` + Math.round(s.fit || 0) + `</span><span class="custombuild-cm-ml">` + T(`cm_m_fit`) + `</span></div>`
                + `<div class="custombuild-cm-metric"><span class="custombuild-cm-mv">` + Math.round(s.impact || 0) + `</span><span class="custombuild-cm-ml">` + T(`cm_m_impact`) + `</span></div>`
                + `<div class="custombuild-cm-metric"><span class="custombuild-cm-mv">` + Math.round(s.nps || 0) + `</span><span class="custombuild-cm-ml">` + T(`cm_m_nps`) + `</span></div>`
                + `<div class="custombuild-cm-metric"><span class="custombuild-cm-mv">` + Math.round(s.margin || 0) + `%</span><span class="custombuild-cm-ml">` + T(`cm_m_margin`) + `</span></div>`;
            return ``
                + `<div class="custombuild-completion">`
                +   `<div class="custombuild-cm-head">`
                +     `<div class="custombuild-cm-score">` + score + `<span class="custombuild-cm-score-max">/100</span></div>`
                +     `<div class="custombuild-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="custombuild-cm-metrics">` + metrics + `</div>`
                +   `<div class="custombuild-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="custombuild-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const fit = Math.round(ds.fit);
            const impact = Math.round(ds.impact);
            const nps = Math.round(ds.nps);
            const margin = ds.margin;

            const wonBid = fit >= this.TARGET_FIT;
            const sustainable = margin >= this.MARGIN_FLOOR && !ds.overBudget;
            const realImpact = impact >= 60;
            const composite = Math.round(
                Math.min(100, fit) * 0.35 +
                impact * 0.30 +
                Math.min(100, nps) * 0.20 +
                Math.max(0, Math.min(100, margin)) * 0.15
            );

            let performanceKey = `grade_lost`;
            if (wonBid && sustainable && realImpact && nps >= this.BENCHMARK_NPS && composite >= 78) performanceKey = `grade_won_right`;
            else if (wonBid && sustainable && realImpact) performanceKey = `grade_strong`;
            else if (wonBid && !sustainable) performanceKey = `grade_unsustainable`;
            else if (wonBid && !realImpact) performanceKey = `grade_thin`;
            else if (fit >= this.TARGET_FIT - 15) performanceKey = `grade_close`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (wonBid && sustainable && realImpact) insights.push(window.mySimulation.t(`insight_won`));
            else if (wonBid && !sustainable) insights.push(window.mySimulation.t(`insight_unsustainable`));
            else if (wonBid && !realImpact) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_lost`));

            if (impact < 45) insights.push(window.mySimulation.t(`insight_lowimpact`));
            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            else if (margin < this.MARGIN_FLOOR) insights.push(window.mySimulation.t(`insight_margin`));
            if (nps >= this.BENCHMARK_NPS && wonBid && sustainable) insights.push(window.mySimulation.t(`insight_renewal`));

            return {
                fit: fit,
                impact: impact,
                nps: nps,
                margin: margin,
                wonBid: wonBid,
                sustainable: sustainable,
                realImpact: realImpact,
                overBudget: ds.overBudget,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_overbudget`);
            if (ds.margin < this.MARGIN_FLOOR && ds.budgetUsed > 0) return window.mySimulation.t(`hint_margin`);
            if (ds.impact < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_impact`);
            if (state.currentPeriod >= 3 && ds.fit < 50) return window.mySimulation.t(`hint_fit`);
            if (ds.fit >= this.TARGET_FIT && ds.impact >= 60 && ds.nps >= this.BENCHMARK_NPS) return window.mySimulation.t(`hint_strong`);
            return null;
        }

